package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;

@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseQ2ClinicalAccessTest extends PhaseP4Fixtures {
 UUID record,request,grant;
 @BeforeEach void scopedGrant(){record=active();role(issuer.id(),"CLINICAL_RECORDS_OPERATOR");role(reviewer.id(),"CLINICAL_RECORDS_OPERATOR");db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id IN(?,?)",issuer.session(),reviewer.session());care.message(learner.id(),learner.session(),record,UUID.randomUUID(),"SYNTHETIC_Q2_PROTECTED_CLINICAL_TEXT");request=care.requestAccess(issuer.id(),issuer.session(),record,"MESSAGES","SYNTHETIC-INDEPENDENT-RECORD-CASE",Instant.now().plusSeconds(300));grant=care.approveAccess(reviewer.id(),reviewer.session(),request,1);}
 @Test void exactScopePositiveReadIsAuditedAndNoAdminOverrideExists(){assertThat(care.messages(issuer.id(),issuer.session(),record,0).toString()).contains("SYNTHETIC_Q2_PROTECTED_CLINICAL_TEXT");assertThat(db.queryForObject("SELECT count(*) FROM clinic_access_audit WHERE grant_id=? AND action='MESSAGES_READ'",Integer.class,grant)).isEqualTo(1);assertThatThrownBy(()->care.messages(other.id(),other.session(),record,0)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->care.notes(issuer.id(),issuer.session(),record,"PROFESSIONAL_NOTES")).isInstanceOf(ForbiddenException.class);}
 @Test void newDeviceCannotReuseOldSessionGrant(){var a=PhaseIFixtures.session(db,users,tokens,issuer.id());db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",a.session());assertThatThrownBy(()->care.messages(issuer.id(),a.session(),record,0)).isInstanceOf(ForbiddenException.class);}
 @Test void revokedApprovalSessionImmediatelyRemovesRecordAccess(){db.update("UPDATE user_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?",reviewer.session());assertThatThrownBy(()->care.messages(issuer.id(),issuer.session(),record,0)).isInstanceOf(ForbiddenException.class);}
 @Test void roleRemovalAndRegrantCannotRestoreEarlierAccess(){db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='CLINICAL_RECORDS_OPERATOR')",reviewer.id());role(reviewer.id(),"CLINICAL_RECORDS_OPERATOR");assertThatThrownBy(()->care.messages(issuer.id(),issuer.session(),record,0)).isInstanceOf(ForbiddenException.class);assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM clinic_record_access_grants WHERE id=?",Boolean.class,grant)).isTrue();}
 @Test void newCategoryPolicyInvalidatesOldGrant(){care.policy(issuer.id(),new ClinicalCare.RecordPolicy("q2-policy-"+UUID.randomUUID(),"MESSAGES","DIRECT",7,null,"SYNTHETIC-NEW-CATEGORY-PROCESSING-APPROVAL",Instant.now().plusSeconds(3600)));assertThatThrownBy(()->care.messages(issuer.id(),issuer.session(),record,0)).isInstanceOf(ForbiddenException.class);}
 @Test void requestWithdrawalInvalidatesGrantAndCannotBeReapproved(){care.withdrawAccessRequest(issuer.id(),issuer.session(),request);assertThatThrownBy(()->care.messages(issuer.id(),issuer.session(),record,0)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->care.approveAccess(reviewer.id(),reviewer.session(),request,1)).isInstanceOf(ConflictException.class);}
 @Test void requestAndGrantScopeCannotBeChangedInPlace(){assertThatThrownBy(()->db.update("UPDATE clinic_record_access_requests SET category='PROFESSIONAL_NOTES' WHERE id=?",request)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void historicalUnboundRequestsAreNotSilentlyApproved(){UUID old=db.queryForObject("INSERT INTO clinic_record_access_requests(encounter_id,operator_id,category,purpose_reference,expires_at) VALUES(?,?,'MESSAGES','SYNTHETIC-HISTORICAL-UNBOUND',CURRENT_TIMESTAMP+INTERVAL '1 hour') RETURNING id",UUID.class,record,other.id());assertThatThrownBy(()->care.approveAccess(reviewer.id(),reviewer.session(),old,1)).isInstanceOf(ConflictException.class);}
}
